using System;
using System.Collections.Generic;
using TMPro;
using UnityEngine;
using UnityEngine.UI;

namespace T2U.Kit
{
    /// <summary>
    /// The states of a UI screen generated by the UI layout importer: what the web UI did by switching a CSS class on
    /// an element (cls('army.guard.up', 'no', true)) is <c>refs.State("army.guard.up", "no", true)</c> here.
    /// For every element that has states the importer stored how it rests and what each state — and each combination of
    /// its states — changes on it and inside it (another skin, a colour, a place, a size).
    /// </summary>
    public sealed class UiStates : MonoBehaviour
    {
        [Serializable]
        public sealed class Change
        {
            public RectTransform target;
            public bool setRect; public Vector2 anchoredPosition, sizeDelta;
            /// <summary>The state pins the element by another edge (web: top → bottom): the edge that stays when it grows.</summary>
            public bool setPivot; public Vector2 pivot;
            public bool setSkin; public Image skin; public Sprite sprite; public Vector2 skinMin, skinMax;
            public bool setColor; public Graphic graphic; public Color color;
            public bool setFont; public TMP_Text text; public Color fontColor; public float fontSize;
            public bool setAlpha; public CanvasGroup group; public float alpha;
            public bool setActive; public bool active;
            /// <summary>CSS animation the web plays in this state ("pulse 0.8s ease-in-out infinite alternate"), "" for none. Played by the element's <see cref="UiAnim"/>.</summary>
            public bool setAnim; public string anim;

            /// <param name="anims">when given, the animation is only noted there (the last state that sets it wins) and played by the caller</param>
            public void Apply(Dictionary<RectTransform, string> anims = null)
            {
                if (target == null) return;
                if (setPivot) target.pivot = pivot;
                if (setRect) { target.anchoredPosition = anchoredPosition; target.sizeDelta = sizeDelta; }
                if (setSkin && skin != null)
                {
                    skin.enabled = sprite != null;
                    skin.sprite = sprite;
                    if (sprite != null && skin.type != Image.Type.Filled) skin.type = sprite.border != Vector4.zero ? Image.Type.Sliced : Image.Type.Simple;
                    var rt = skin.rectTransform; rt.offsetMin = skinMin; rt.offsetMax = skinMax;
                }
                if (setColor && graphic != null) graphic.color = color;
                if (setFont && text != null) { text.color = fontColor; text.fontSize = fontSize; }
                if (setAlpha && group != null) group.alpha = alpha;
                if (setActive) target.gameObject.SetActive(active);
                if (setAnim)
                {
                    if (anims != null) anims[target] = anim ?? "";
                    else PlayAnim(target, anim);
                }
            }
        }

        /// <summary>CSS restarts an animation only when its name list changes.</summary>
        static void PlayAnim(RectTransform target, string anim)
        {
            var a = target.GetComponent<UiAnim>();
            if (a != null && a.Current != (anim ?? "")) a.Play(anim);
        }

        static readonly Dictionary<RectTransform, string> Pending = new Dictionary<RectTransform, string>();

        [Serializable]
        public sealed class Variant
        {
            /// <summary>The states that are on, in the host's order, joined by a space ("no power").</summary>
            public string on;
            public List<Change> changes = new List<Change>();
        }

        [Serializable]
        public sealed class Host
        {
            public string name;
            public string[] states;
            /// <summary>Bit i = states[i] is on.</summary>
            public int mask;
            /// <summary>How everything a state can touch looks with no state on.</summary>
            public List<Change> rest = new List<Change>();
            public List<Variant> variants = new List<Variant>();
        }

        public List<Host> hosts = new List<Host>();
        Dictionary<string, Host> _map;

        Host Find(string host)
        {
            if (_map == null)
            {
                _map = new Dictionary<string, Host>();
                foreach (var h in hosts) _map[h.name] = h;
            }
            return _map.TryGetValue(host, out var r) ? r : null;
        }

        public bool Has(string host, string state)
        {
            var h = Find(host);
            return h != null && Array.IndexOf(h.states, state) >= 0;
        }

        public bool IsOn(string host, string state)
        {
            var h = Find(host);
            int i = h == null ? -1 : Array.IndexOf(h.states, state);
            return i >= 0 && (h.mask & (1 << i)) != 0;
        }

        /// <summary>Switches a state of an element on or off (no effect, and no cost, when it already is).</summary>
        public void Set(string host, string state, bool on)
        {
            var h = Find(host);
            if (h == null) return; // the web switches classes that change nothing on some elements: nothing to do
            int i = Array.IndexOf(h.states, state);
            if (i < 0) return;
            int mask = on ? h.mask | (1 << i) : h.mask & ~(1 << i);
            if (mask == h.mask) return;
            h.mask = mask;
            Apply(h);
        }

        /// <summary>Puts an element into the look of its current states (the importer calls this for states that start on).</summary>
        public void Apply(Host h)
        {
            Pending.Clear();
            ApplyLooks(h);
            foreach (var kv in Pending) PlayAnim(kv.Key, kv.Value);
            Pending.Clear();
        }

        void ApplyLooks(Host h)
        {
            foreach (var c in h.rest) c.Apply(Pending);
            if (h.mask == 0) return;
            var key = "";
            for (int i = 0; i < h.states.Length; i++) if ((h.mask & (1 << i)) != 0) key += (key.Length > 0 ? " " : "") + h.states[i];
            foreach (var v in h.variants) if (v.on == key) { foreach (var c in v.changes) c.Apply(Pending); return; }
            // a combination that was not exported (more than three states at once): each state on its own, in order
            for (int i = 0; i < h.states.Length; i++)
            {
                if ((h.mask & (1 << i)) == 0) continue;
                foreach (var v in h.variants) if (v.on == h.states[i]) foreach (var c in v.changes) c.Apply(Pending);
            }
        }
    }
}
